<script setup>
import {ref} from 'vue';import {requestDuration,durationReceiptMessage,positiveMinutes,originalRequestReference} from '../api/duration.js';
const items=ref([]),caps=ref({canEdit:false,canPublish:false}),csrf=ref(''),name=ref(''),minutes=ref(''),projectId=ref(''),versionNo=ref(''),reason=ref(''),selected=ref(null),status=ref('尚未核验配置权限'),pending=ref(false),unresolved=ref(false),requestRef=ref('');
const nextCursor=ref(null),namespace=ref('');function retainPending(){if(namespace.value)sessionStorage.setItem('adc.duration.pending:'+namespace.value,requestRef.value);}function clearPending(){if(namespace.value)sessionStorage.removeItem('adc.duration.pending:'+namespace.value);}
async function run(work){if(pending.value)return;pending.value=true;try{await work();}catch(e){status.value=e.message==='NETWORK_OR_RESULT_UNKNOWN'?'结果可能未知，请保留原请求，不重复发布':'配置不可用或无权访问';}finally{pending.value=false;}}
async function load(after='0'){await run(async()=>{const r=await requestDuration(after==='0'?'/api/v1/staff/duration-projects':'/api/v1/staff/duration-projects?after='+after+'&limit=50');items.value=r.items||[];nextCursor.value=r.nextCursor||null;caps.value=r.capabilities||{canEdit:false,canPublish:false};csrf.value=r.csrfToken||'';namespace.value=r.requestNamespace||'';const saved=sessionStorage.getItem('adc.duration.pending:'+namespace.value);if(saved&&namespace.value){requestRef.value=saved;unresolved.value=true;}status.value=unresolved.value?'存在待核对原请求，请先查询结果':'配置权限已核验';});}
async function loadVersion(){await run(async()=>{selected.value=await requestDuration(`/api/v1/staff/duration-projects/${projectId.value}/versions/${versionNo.value}`);name.value=selected.value.projectName;minutes.value=String(selected.value.durationMinutes);status.value='已读取准确版本';});}
async function submit(kind){await run(async()=>{const key=crypto.randomUUID();let path,body,method='POST';if(kind==='create'){path='/api/v1/headquarters/duration-project-drafts';body={projectName:name.value,durationMinutes:positiveMinutes(minutes.value)};if(projectId.value){body.projectId=projectId.value;body.expectedBaseVersion=Number(versionNo.value);}}else{if(!selected.value)throw Error('VERSION_REQUIRED');const v=selected.value;path=`/api/v1/headquarters/duration-projects/${v.projectId}/versions/${v.versionNo}/`+(kind==='edit'?'draft':'publications');if(kind==='edit'){method='PUT';body={projectName:name.value,durationMinutes:positiveMinutes(minutes.value),reason:reason.value,expectedStateToken:v.stateToken};}else{const current=items.value.find(x=>x.projectId===v.projectId);body={expectedDraftToken:v.stateToken,expectedCurrentRef:current?{projectId:current.projectId,versionNo:current.versionNo}:null,reason:reason.value};}}requestRef.value=originalRequestReference(namespace.value,kind==='create'?'DURATION_DRAFT_CREATE':kind==='edit'?'DURATION_DRAFT_EDIT':'DURATION_PUBLISH',key);unresolved.value=true;retainPending();const r=await requestDuration(path,{method,body,csrf:csrf.value,key});if(r.requestReference!==requestRef.value)throw Error('INVALID_RESPONSE');unresolved.value=r.status==='UNKNOWN'||r.auditPersistence!=='CONFIRMED';if(!unresolved.value)clearPending();status.value=durationReceiptMessage(r);if(r.versionRef){projectId.value=r.versionRef.projectId;versionNo.value=String(r.versionRef.versionNo);selected.value=null;}});}
async function recover(){await run(async()=>{const r=await requestDuration('/api/v1/headquarters/duration-commands/'+requestRef.value);status.value=durationReceiptMessage(r);unresolved.value=r.status==='UNKNOWN'||r.auditPersistence!=='CONFIRMED';if(!unresolved.value)clearPending();});}
</script>
<template><main><h1>总部项目标准时长配置</h1><p>真实身份和配置来源未接入时，操作保持关闭。分钟无默认值；发布不修改既有预约。</p><button @click="load()" :disabled="pending">核验配置权限</button><p role="status">{{status}}</p><ul><li v-for="item in items" :key="item.projectId">{{item.projectName}} · {{item.durationMinutes}}分钟 · v{{item.versionNo}}</li></ul><button v-if="nextCursor" @click="load(nextCursor)" :disabled="pending">下一页</button><section v-if="caps.canEdit||caps.canPublish"><label>项目ID<input aria-label="项目ID" v-model="projectId" /></label><label>版本号<input aria-label="版本号" v-model="versionNo" /></label><button @click="loadVersion" :disabled="pending">读取版本</button><label>项目名称<input aria-label="项目名称" :readonly="!caps.canEdit" v-model="name" /></label><label>标准分钟<input aria-label="标准分钟" :readonly="!caps.canEdit" v-model="minutes" /></label><label>操作原因<input aria-label="操作原因" v-model="reason" /></label><template v-if="caps.canEdit"><button @click="submit('create')" :disabled="pending||unresolved">新建版本草稿</button><button @click="submit('edit')" :disabled="pending||unresolved||!selected">保存草稿</button></template><button v-if="caps.canPublish" @click="submit('publish')" :disabled="pending||unresolved||!selected">发布版本</button></section><label>原请求引用<input aria-label="原请求引用" v-model="requestRef" /></label><button @click="recover" :disabled="pending||!requestRef">核对原请求</button></main></template>
